/// Parses a JSON value as `FilingRecurrenceOccurrences`: `prepare_filing_recurrence_occurrences`, then decodes it.
pub fn parse_filing_recurrence_occurrences(value: Value, unknown_fields: rt::UnknownFields) -> Result<crate::types::FilingRecurrenceOccurrences, rt::ParseError> {
    let value = prepare_filing_recurrence_occurrences(value, unknown_fields)?;
    serde_json::from_value(value).map_err(rt::ParseError::Decode)
}

/// The fields `Holiday` declares, by their wire names.
pub const HOLIDAY_FIELDS: &[&str] = &["id", "calendar", "date", "weekday", "name"];

/// Validates a JSON value as `Holiday`. A null value passes; the errors
/// are empty when the value is valid.
pub fn validate_holiday(value: &Value) -> ValidationErrors {
    let mut errors = ValidationErrors::new();
    if value.is_null() {
        return errors;
    }
    {
        let field = value.get("id");
        if !rt::is_absent(field) {
            errors.set_result("id", scalars::validate_identity_uuid(field));
        }
    }
    {
        let field = value.get("calendar");
        if rt::is_absent(field) {
            errors.push("calendar", ValidationError::required());
        }
        rt::expect_string(&mut errors, "calendar", field);
    }
    {
        let field = value.get("date");
        if !rt::is_absent(field) {
            errors.set_result("date", scalars::validate_temporal_date(field));
        }
    }
    {
        let field = value.get("weekday");
        rt::expect_string(&mut errors, "weekday", field);
    }
    {
        let field = value.get("name");
        if rt::is_absent(field) {
            errors.push("name", ValidationError::required());
        }
        rt::expect_string(&mut errors, "name", field);
    }
    errors
}

/// Validates a `Holiday` object that must be present: its errors are one
/// `object` error.
pub fn validate_holiday_required(value: Option<&Value>) -> rt::ScalarResult {
    rt::require_object(value, validate_holiday)
}

/// Prepares a JSON value as `Holiday`: fills its `@default` values,
/// refuses undeclared keys when asked and validates it, returning the value
/// `parse_holiday` decodes.
pub fn prepare_holiday(value: Value, unknown_fields: rt::UnknownFields) -> Result<Value, rt::ParseError> {
    let Value::Object(object) = value else {
        return Err(rt::ParseError::NotAnObject);
    };
    rt::check_unknown_fields(&object, HOLIDAY_FIELDS, unknown_fields)?;
    let value = Value::Object(object);
    let errors = validate_holiday(&value);
    if !errors.is_empty() {
        return Err(rt::ParseError::Invalid(errors));
    }
    Ok(value)
}

/// Parses a JSON value as `Holiday`: `prepare_holiday`, then decodes it.
pub fn parse_holiday(value: Value, unknown_fields: rt::UnknownFields) -> Result<crate::types::Holiday, rt::ParseError> {
    let value = prepare_holiday(value, unknown_fields)?;
    serde_json::from_value(value).map_err(rt::ParseError::Decode)
}
